SELECT id, knowledge_base_id, document_id, user_id, chunk_index, content, embedding, char_count, created_at
FROM knowledge_chunk
WHERE knowledge_base_id = #{knowledgeBaseId}
  AND user_id = #{userId}
ORDER BY document_id, chunk_index

SELECT COUNT(*)
FROM knowledge_chunk
WHERE knowledge_base_id = #{knowledgeBaseId}
